// strip-null-bytes.js
// 根治方案：Docusaurus 在生成「中文分类路径」的 autogenerated 侧边栏 category 链接时，
// 会在 SSR HTML 的 href 中间插入位置不固定的 \x00 字节（跨 Node 20/22、跨 3.9/3.10 均复现），
// 导致这些链接在 GitHub Pages（大小写/路径敏感）上 404。
// 由于空字节只插在「本就正确的 URL」中间，post-build 阶段剥离 \x00 即可还原正确链接。
// 仅处理文本资源（html/json/js/css/svg/xml/txt/md...），跳过图片/字体等二进制，避免损坏。

const fs = require("fs");
const path = require("path");

const BUILD_DIR = path.join(process.cwd(), "build");

// 仅这些文本扩展名参与剥离；其余（webp/png/woff2 等）一律跳过
const TEXT_EXT = new Set([
  ".html", ".htm", ".xhtml",
  ".xml", ".json", ".js", ".mjs", ".cjs",
  ".css", ".svg", ".txt", ".md", ".mdx",
  ".yml", ".yaml", ".map", ".webmanifest",
]);

function walk(dir, out) {
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, ent.name);
    if (ent.isDirectory()) walk(full, out);
    else out.push(full);
  }
}

function main() {
  if (!fs.existsSync(BUILD_DIR)) {
    console.error(`[strip-null] build 目录不存在: ${BUILD_DIR}，跳过`);
    process.exit(0);
  }
  const files = [];
  walk(BUILD_DIR, files);

  let scanned = 0;
  let fixed = 0;
  let totalNulls = 0;
  for (const f of files) {
    const ext = path.extname(f).toLowerCase();
    if (!TEXT_EXT.has(ext)) continue; // 二进制资源跳过
    scanned++;
    const buf = fs.readFileSync(f);
    if (!buf.includes(0x00)) continue;
    const text = buf.toString("utf8");
    const count = (text.match(/\x00/g) || []).length;
    const cleaned = text.replace(/\x00/g, "");
    fs.writeFileSync(f, cleaned, "utf8");
    fixed++;
    totalNulls += count;
  }
  console.log(
    `[strip-null] 扫描文本文件 ${scanned}，修复含空字节文件 ${fixed}，共剥离空字节 ${totalNulls} 个`
  );
}

main();
